content:
:root {
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --bg-gradient: linear-gradient(135deg, #f0f4f8 0%, #e2e8f0 100%);
  --card-bg: #ffffff;
  --text-main: #1e293b;
  --text-muted: #64748b;
  --border-color: #e2e8f0;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.06), 0 1px 2px rgba(0, 0, 0, 0.04);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -1px rgba(0, 0, 0, 0.04);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: var(--bg-gradient);
  color: var(--text-main);
  min-height: 100vh;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

/* アクセシビリティ: キーボード操作時のフォーカス表示 */
button:focus-visible,
input:focus-visible,
.list-item:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 2px;
}

/* アプリケーション全体コンテナ */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px 48px;
}

/* ヘッダー */
.app-header {
  text-align: center;
  margin-bottom: 28px;
}

.header-title {
  font-size: 1.85rem;
  font-weight: 700;
  color: #0f172a;
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.header-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* メインレイアウト（グラフとリストの2カラム） */
.main-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 880px) {
  .main-layout {
    grid-template-columns: 1fr 1fr;
    align-items: start;
  }
}

/* グラフセクション */
.chart-section {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.chart-card {
  background: var(--card-bg);
  border-radius: var(--radius-lg);
  padding: 24px 20px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  align-items: center;
}

.chart-wrapper {
  position: relative;
  width: 100%;
  height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* 円グラフ中央の合計表示 */
.center-summary {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 140px;
  height: 140px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(4px);
  box-shadow: var(--shadow-sm);
}

.center-label {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 2px;
}

.center-amount {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--text-main);
  white-space: nowrap;
}

/* 詳細パネル（ハイライトカード） */
.detail-card {
  background: var(--card-bg);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-md);
  border-left: 6px solid var(--primary-color);
  position: relative;
  animation: fadeIn 0.25s ease-out;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.detail-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.detail-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  border-radius: 9999px;
  font-size: 0.85rem;
  font-weight: 600;
  color: #ffffff;
}

.detail-close-btn {
  background: transparent;
  border: none;
  color: var(--text-muted);
  font-size: 1.25rem;
  line-height: 1;
  cursor: pointer;
  min-width: 44px;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
  border-radius: var(--radius-sm);
  transition: background 0.15s, color 0.15s;
}

.detail-close-btn:hover {
  background: #f1f5f9;
  color: var(--text-main);
}

.detail-amount {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 4px;
}

.detail-percent {
  font-size: 0.95rem;
  color: var(--text-muted);
  font-weight: 500;
  margin-bottom: 8px;
}

.detail-note {
  font-size: 0.875rem;
  color: #475569;
  background: #f8fafc;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  margin-top: 8px;
}

/* リストセクション */
.list-section {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.list-card {
  background: var(--card-bg);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--border-color);
}

.list-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-color);
}

.list-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-main);
}

.list-container {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 380px;
  overflow-y: auto;
  padding-right: 4px;
}

/* スクロールバーのスタイリング */
.list-container::-webkit-scrollbar {
  width: 6px;
}
.list-container::-webkit-scrollbar-thumb {
  background-color: #cbd5e1;
  border-radius: 3px;
}

/* 各リスト項目 */
.list-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  min-height: 48px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
  background: #ffffff;
  cursor: pointer;
  transition: all 0.2s ease;
}

.list-item:hover {
  background: #f8fafc;
  border-color: #cbd5e1;
  transform: translateY(-1px);
}

.list-item-active {
  background: #eff6ff !important;
  border-color: var(--primary-color) !important;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
}

.item-color-dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  flex-shrink: 0;
  margin-right: 12px;
}

.item-info {
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 0;
}

.item-name {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-main);
  margin-right: 8px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.item-subtext {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.item-amount {
  font-size: 1rem;
  font-weight: 700;
  color: #0f172a;
  margin-right: 12px;
  white-space: nowrap;
}

.item-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.btn-edit,
.btn-delete {
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  padding: 8px;
  min-width: 44px;
  min-height: 44px;
  font-size: 0.95rem;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

.btn-edit:hover {
  background: #f1f5f9;
  color: var(--primary-color);
  border-color: #cbd5e1;
}

.btn-delete:hover {
  background: #fef2f2;
  color: var(--danger-color);
  border-color: #fca5a5;
}

/* 追加フォーム */
.add-form {
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px dashed var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.form-row {
  display: flex;
  gap: 8px;
  align-items: center;
  flex-wrap: wrap;
}

.input-text,
.input-number {
  flex: 1;
  min-width: 120px;
  min-height: 44px;
  padding: 8px 12px;
  font-size: 0.9rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  outline: none;
  background: #ffffff;
  color: var(--text-main);
  transition: border-color 0.15s, box-shadow 0.15s;
}

.input-text:focus,
.input-number:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.15);
}

.input-color {
  width: 44px;
  height: 44px;
  padding: 2px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  cursor: pointer;
  background: #ffffff;
}

.btn-add {
  background: var(--primary-color);
  color: #ffffff;
  border: none;
  border-radius: var(--radius-sm);
  min-height: 44px;
  padding: 8px 16px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: background 0.15s, transform 0.05s;
  white-space: nowrap;
}

.btn-add:hover {
  background: var(--primary-hover);
}

.btn-add:active {
  transform: translateY(1px);
}

.empty-message {
  text-align: center;
  color: var(--text-muted);
  font-size: 0.9rem;
  padding: 32px 16px;
}

export interface ExpenseCategoryItem {
  id: string;
  name: string;
  amount: number;
  color: string;
  icon: string;
  note: string;
}

/** 新規支出項目作成用の入力DTO型 */
export interface CreateExpenseItemDTO {
  name: string;
  amount: number;
  color: string;
  icon?: string;
  note?: string;
}

export type CreateExpenseInput = CreateExpenseItemDTO;

/** Rechartsツールチップ用のペイロード型 */
export interface ExpenseTooltipPayloadItem {
  payload: ExpenseCategoryItem;
  value?: number;
  name?: string;
  color?: string;
  [key: string]: unknown;
}

/** Rechartsカスタムツールチップ用Props */
export interface ExpenseChartTooltipProps {
  active?: boolean;
  payload?: ExpenseTooltipPayloadItem[];
  label?: string | number;
}

export interface ExpenseDetailProps {
  selectedItem?: ExpenseCategoryItem | null;
  totalAmount?: number;
  onClose?: () => void;
}

export interface ExpensePieChartProps {
  data?: ExpenseCategoryItem[];
  selectedId?: string | null;
  onSelect?: (item: ExpenseCategoryItem) => void;
  totalAmount?: number;
}

export interface ExpenseListProps {
  items?: ExpenseCategoryItem[];
  selectedId?: string | null;
  onSelect?: (item: ExpenseCategoryItem) => void;
  onUpdateAmount?: (id: string, amount: number) => void;
  onAddItem?: ((name: string, amount: number, color: string) => void) &
    ((input: CreateExpenseItemDTO) => void);
  onDeleteItem?: (id: string) => void;
}

import { FC } from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';
import { ExpenseCategoryItem, ExpensePieChartProps } from '../types';

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{
    payload: ExpenseCategoryItem;
  }>;
  totalAmount: number;
}

const CustomTooltip: FC<CustomTooltipProps> = ({ active, payload, totalAmount }) => {
  if (active && payload && payload.length > 0 && payload[0]?.payload) {
    const item = payload[0].payload;
    const percent =
      totalAmount > 0 && !isNaN(item.amount)
        ? ((item.amount / totalAmount) * 100).toFixed(1)
        : '0.0';

    return (
      <div
        style={{
          backgroundColor: '#ffffff',
          padding: '8px 12px',
          border: '1px solid #e2e8f0',
          borderRadius: '8px',
          boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
          fontSize: '0.875rem',
        }}
      >
        <div style={{ fontWeight: 600, color: item.color, marginBottom: 2 }}>
          {item.icon} {item.name}
        </div>
        <div style={{ fontWeight: 700, color: '#0f172a' }}>
          ¥{item.amount.toLocaleString('ja-JP')}
        </div>
        <div style={{ color: '#64748b', fontSize: '0.75rem' }}>
          構成比: {percent}%
        </div>
      </div>
    );
  }
  return null;
};

const ExpensePieChart: FC<ExpensePieChartProps> = ({
  data = [],
  selectedId = null,
  onSelect,
  totalAmount = 0,
}) => {
  const formattedTotal = totalAmount.toLocaleString('ja-JP');
  const hasData = data.length > 0 && totalAmount > 0;

  const handlePieClick = (entry: ExpenseCategoryItem) => {
    if (onSelect) {
      onSelect(entry);
    }
  };

  return (
    <div className="chart-wrapper">
      {hasData ? (
        <ResponsiveContainer width="100%" height={320}>
          <PieChart>
            <Tooltip content={<CustomTooltip totalAmount={totalAmount} />} />
            <Pie
              data={data}
              dataKey="amount"
              nameKey="name"
              cx="50%"
              cy="50%"
              innerRadius={80}
              outerRadius={125}
              paddingAngle={2}
              onClick={handlePieClick}
              style={{ cursor: 'pointer', outline: 'none' }}
            >
              {data.map((entry) => {
                const isSelected = entry.id === selectedId;
                return (
                  <Cell
                    key={entry.id}
                    fill={entry.color}
                    stroke={isSelected ? '#1e293b' : '#ffffff'}
                    strokeWidth={isSelected ? 3 : 1}
                    opacity={selectedId ? (isSelected ? 1 : 0.45) : 1}
                  />
                );
              })}
            </Pie>
          </PieChart>
        </ResponsiveContainer>
      ) : (
        <div
          style={{
            height: '320px',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: '#64748b',
            fontSize: '0.9rem',
          }}
        >
          データがありません
        </div>
      )}
      <div className="center-summary">
        <span className="center-label">今月の総支出</span>
        <span className="center-amount">¥{formattedTotal}</span>
      </div>
    </div>
  );
};

export default ExpensePieChart;

import { FC, useEffect, useState, ChangeEvent } from 'react';
import { ExpenseDetailProps } from '../types';

interface ExtendedExpenseDetailProps extends ExpenseDetailProps {
  onUpdateNote?: (id: string, note: string) => void;
}

const ExpenseDetail: FC<ExtendedExpenseDetailProps> = ({
  selectedItem = null,
  totalAmount = 0,
  onClose,
  onUpdateNote,
}) => {
  const [isEditingNote, setIsEditingNote] = useState<boolean>(false);
  const [noteText, setNoteText] = useState<string>('');

  useEffect(() => {
    if (selectedItem) {
      setNoteText(selectedItem.note || '');
      setIsEditingNote(false);
    }
  }, [selectedItem?.id, selectedItem?.note]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && onClose) {
        onClose();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [onClose]);

  if (!selectedItem) {
    return null;
  }

  const safeTotal = typeof totalAmount === 'number' && !isNaN(totalAmount) ? totalAmount : 0;
  const safeAmount =
    typeof selectedItem.amount === 'number' && !isNaN(selectedItem.amount)
      ? selectedItem.amount
      : 0;

  const percent =
    safeTotal > 0 && safeAmount >= 0
      ? ((safeAmount / safeTotal) * 100).toFixed(1)
      : '0.0';

  const formattedAmount = safeAmount.toLocaleString('ja-JP');

  const handleClose = () => {
    if (onClose) {
      onClose();
    }
  };

  const handleSaveNote = () => {
    if (onUpdateNote) {
      onUpdateNote(selectedItem.id, noteText);
    } else {
      selectedItem.note = noteText;
    }
    setIsEditingNote(false);
  };

  const handleCancelNote = () => {
    setNoteText(selectedItem.note || '');
    setIsEditingNote(false);
  };

  return (
    <div
      className="detail-card"
      style={{ borderLeftColor: selectedItem.color }}
    >
      <div className="detail-header">
        <span
          className="detail-badge"
          style={{ backgroundColor: selectedItem.color }}
        >
          <span>{selectedItem.icon}</span>
          <span>{selectedItem.name}</span>
        </span>
        <button
          type="button"
          className="detail-close-btn"
          onClick={handleClose}
          aria-label="詳細を閉じる (Esc)"
          title="閉じる (Esc)"
        >
          ✕
        </button>
      </div>

      <div className="detail-amount">¥{formattedAmount}</div>
      <div className="detail-percent">全体に対する構成比: {percent}%</div>
      <div className="detail-note">
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 4 }}>
          <strong>内訳メモ:</strong>
          {!isEditingNote && (
            <button
              type="button"
              className="btn-edit"
              onClick={() => setIsEditingNote(true)}
              title="メモを編集"
              style={{ fontSize: '0.75rem', padding: '2px 6px' }}
            >
              ✎ 編集
            </button>
          )}
        </div>

        {isEditingNote ? (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '6px', marginTop: '6px' }}>
            <input
              type="text"
              className="input-text"
              value={noteText}
              onChange={(e: ChangeEvent<HTMLInputElement>) => setNoteText(e.target.value)}
              placeholder="内訳メモを入力"
              autoFocus
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleSaveNote();
                if (e.key === 'Escape') {
                  e.stopPropagation();
                  handleCancelNote();
                }
              }}
            />
            <div style={{ display: 'flex', gap: '6px', justifyContent: 'flex-end' }}>
              <button
                type="button"
                className="btn-edit"
                onClick={handleSaveNote}
                title="保存"
                style={{ fontSize: '0.8rem', padding: '4px 10px' }}
              >
                保存
              </button>
              <button
                type="button"
                className="btn-delete"
                onClick={handleCancelNote}
                title="キャンセル"
                style={{ fontSize: '0.8rem', padding: '4px 10px' }}
              >
                キャンセル
              </button>
            </div>
          </div>
        ) : (
          <span>{selectedItem.note || '詳細なメモはありません'}</span>
        )}
      </div>
    </div>
  );
};

export default ExpenseDetail;

import { useState, FC, FormEvent, MouseEvent, KeyboardEvent } from 'react';
import { ExpenseCategoryItem, ExpenseListProps } from '../types';

interface ExtendedExpenseListProps extends ExpenseListProps {
  onAddItem: (name: string, amount: number, color: string, icon?: string, note?: string) => void;
}

const ExpenseList: FC<ExtendedExpenseListProps> = ({
  items = [],
  selectedId = null,
  onSelect,
  onUpdateAmount,
  onAddItem,
  onDeleteItem,
}) => {
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editAmountText, setEditAmountText] = useState<string>('');
  const [editError, setEditError] = useState<string | null>(null);

  // 新規追加フォーム用の入力状態
  const [newName, setNewName] = useState<string>('');
  const [newAmount, setNewAmount] = useState<string>('');
  const [newColor, setNewColor] = useState<string>('#06b6d4');
  const [newIcon, setNewIcon] = useState<string>('🏷️');
  const [newNote, setNewNote] = useState<string>('');

  // インライン金額編集の開始
  const handleStartEdit = (e: MouseEvent, item: ExpenseCategoryItem) => {
    e.stopPropagation();
    setEditingId(item.id);
    setEditAmountText(item.amount.toString());
    setEditError(null);
  };

  // インライン金額変更の確定
  const handleSaveEdit = (e?: MouseEvent | KeyboardEvent, id?: string) => {
    if (e) e.stopPropagation();
    const targetId = id || editingId;
    if (!targetId) return;

    const trimmed = editAmountText.trim();
    const val = parseInt(trimmed, 10);

    if (trimmed === '' || isNaN(val) || val < 0) {
      setEditError('0以上の有効な金額を入力してください');
      return;
    }

    onUpdateAmount?.(targetId, val);
    setEditingId(null);
    setEditError(null);
  };

  // インライン金額変更のキャンセル
  const handleCancelEdit = (e?: MouseEvent | KeyboardEvent) => {
    if (e) e.stopPropagation();
    setEditingId(null);
    setEditError(null);
  };

  const handleEditKeyDown = (e: KeyboardEvent<HTMLInputElement>, id: string) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleSaveEdit(e, id);
    } else if (e.key === 'Escape') {
      e.preventDefault();
      handleCancelEdit(e);
    }
  };

  // 削除処理
  const handleDelete = (e: MouseEvent, id: string) => {
    e.stopPropagation();
    onDeleteItem?.(id);
  };

  // 新規項目の送信
  const handleAddSubmit = (e: FormEvent) => {
    e.preventDefault();
    const trimmedName = newName.trim();
    const parsedAmount = parseInt(newAmount, 10);

    if (!trimmedName || isNaN(parsedAmount) || parsedAmount < 0) {
      return;
    }

    onAddItem?.(trimmedName, parsedAmount, newColor, newIcon, newNote.trim());
    setNewName('');
    setNewAmount('');
    setNewNote('');
  };

  return (
    <div className="list-card">
      <div className="list-header">
        <h2 className="list-title">支出内訳リスト ({items.length}件)</h2>
      </div>

      <div className="list-container">
        {items.length === 0 ? (
          <div className="empty-message">支出項目が登録されていません</div>
        ) : (
          items.map((item) => {
            const isSelected = item.id === selectedId;
            const isEditing = item.id === editingId;

            return (
              <div
                key={item.id}
                className={isSelected ? 'list-item list-item-active' : 'list-item'}
                onClick={() => onSelect?.(item)}
              >
                <div
                  className="item-color-dot"
                  style={{ backgroundColor: item.color }}
                />
                <div className="item-info">
                  <span className="item-name">
                    {item.icon} {item.name}
                  </span>
                  <span className="item-subtext">{item.note}</span>
                </div>

                {isEditing ? (
                  <div
                    style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '4px' }}
                    onClick={(e) => e.stopPropagation()}
                  >
                    <div className="item-actions">
                      <input
                        type="number"
                        className="input-number"
                        style={{
                          width: '100px',
                          padding: '4px 8px',
                          borderColor: editError ? '#ef4444' : undefined,
                        }}
                        value={editAmountText}
                        onChange={(e) => {
                          setEditAmountText(e.target.value);
                          if (editError) setEditError(null);
                        }}
                        onKeyDown={(e) => handleEditKeyDown(e, item.id)}
                        min="0"
                        autoFocus
                      />
                      <button
                        type="button"
                        className="btn-edit"
                        onClick={(e) => handleSaveEdit(e, item.id)}
                        title="保存 (Enter)"
                      >
                        ✓
                      </button>
                      <button
                        type="button"
                        className="btn-delete"
                        onClick={handleCancelEdit}
                        title="キャンセル (Esc)"
                      >
                        ✕
                      </button>
                    </div>
                    {editError && (
                      <span style={{ color: '#ef4444', fontSize: '0.75rem' }}>
                        {editError}
                      </span>
                    )}
                  </div>
                ) : (
                  <>
                    <div className="item-amount">
                      ¥{item.amount.toLocaleString('ja-JP')}
                    </div>
                    <div className="item-actions">
                      <button
                        type="button"
                        className="btn-edit"
                        onClick={(e) => handleStartEdit(e, item)}
                        title="金額を変更"
                      >
                        ✎
                      </button>
                      <button
                        type="button"
                        className="btn-delete"
                        onClick={(e) => handleDelete(e, item.id)}
                        title="削除"
                      >
                        🗑
                      </button>
                    </div>
                  </>
                )}
              </div>
            );
          })
        )}
      </div>

      <form className="add-form" onSubmit={handleAddSubmit}>
        <div className="form-row">
          <select
            className="input-text"
            style={{ maxWidth: '75px', padding: '8px' }}
            value={newIcon}
            onChange={(e) => setNewIcon(e.target.value)}
            title="アイコンを選択"
          >
            <option value="🏷️">🏷️</option>
            <option value="🍚">🍚</option>
            <option value="🏠">🏠</option>
            <option value="💡">💡</option>
            <option value="📱">📱</option>
            <option value="🎮">🎮</option>
            <option value="🧴">🧴</option>
            <option value="💊">💊</option>
            <option value="🚗">🚗</option>
            <option value="☕">☕</option>
            <option value="👕">👕</option>
          </select>
          <input
            type="text"
            className="input-text"
            placeholder="項目名（例: カフェ・お茶代）"
            value={newName}
            onChange={(e) => setNewName(e.target.value)}
            required
          />
          <input
            type="number"
            className="input-number"
            placeholder="金額 (円)"
            value={newAmount}
            onChange={(e) => setNewAmount(e.target.value)}
            min="0"
            required
          />
          <input
            type="color"
            className="input-color"
            value={newColor}
            onChange={(e) => setNewColor(e.target.value)}
            title="カラーを選択"
          />
        </div>
        <div className="form-row">
          <input
            type="text"
            className="input-text"
            placeholder="内訳メモ（例: 週末のリフレッシュカフェ利用など）"
            value={newNote}
            onChange={(e) => setNewNote(e.target.value)}
          />
          <button type="submit" className="btn-add">
            ＋ 追加
          </button>
        </div>
      </form>
    </div>
  );
};

export default ExpenseList;

import { useState, useEffect, FC } from 'react';
import { ExpenseCategoryItem } from './types';
