    note: '定期受診代、処方薬、民間生命・医療保険の月額保険料',
  },
];

const generateUniqueId = (): string => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return `exp-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
};

const App: FC = () => {
  const [expenses, setExpenses] = useState<ExpenseCategoryItem[]>(() => {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        if (Array.isArray(parsed)) {
          return parsed;
        }
      }
    } catch {
      // localStorageのパースエラー時は初期値を使用
    }
    return INITIAL_EXPENSES;
  });

  const [selectedId, setSelectedId] = useState<string | null>(() => {
    return expenses.length > 0 ? expenses[0].id : null;
  });

  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
    } catch {
      // 保存容量超過等のエラーハンドリング
    }
  }, [expenses]);

  // 合計金額の計算
  const totalAmount = expenses.reduce((sum, item) => sum + item.amount, 0);

  // 現在選択されている項目オブジェクトの取得
  const selectedItem = expenses.find((item) => item.id === selectedId) || null;

  // 項目選択ハンドラ（グラフ・リスト共通）
  const handleSelect = (item: ExpenseCategoryItem) => {
    setSelectedId(item.id);
  };

  // 詳細パネルの閉じるボタン
  const handleCloseDetail = () => {
    setSelectedId(null);
  };

  // メモの更新ハンドラ
  const handleUpdateNote = (id: string, note: string) => {
    setExpenses((prev) =>
      prev.map((item) => (item.id === id ? { ...item, note } : item))
    );
  };

  // 金額のインライン変更ハンドラ
  const handleUpdateAmount = (id: string, newAmount: number) => {
    setExpenses((prev) =>
      prev.map((item) => (item.id === id ? { ...item, amount: newAmount } : item))
    );
  };

  // 新規項目の追加ハンドラ
  const handleAddItem = (
    name: string,
    amount: number,
    color: string,
    icon: string = '🏷️',
    note: string = ''
  ) => {
    const newItem: ExpenseCategoryItem = {
      id: generateUniqueId(),
      name,
      amount,
      color,
      icon: icon || '🏷️',
      note: note || '新規登録された支出項目',
    };
    setExpenses((prev) => [...prev, newItem]);
    setSelectedId(newItem.id);
  };

  // 項目の削除ハンドラ
  const handleDeleteItem = (id: string) => {
    setExpenses((prev) => prev.filter((item) => item.id !== id));
    if (selectedId === id) {
      setSelectedId(null);
    }
  };

  // 初期データへのリセットハンドラ
  const handleResetData = () => {
    setExpenses(INITIAL_EXPENSES);
    setSelectedId(INITIAL_EXPENSES[0]?.id || null);
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch {
      // localStorageのエラーハンドリング
    }
  };

  return (
    <div className="app-container">
      <header className="app-header">
        <h1 className="header-title">家計簿 支出内訳ダッシュボード</h1>
        <p className="header-subtitle">
          円グラフの各項目をクリックして金額・構成比・内訳詳細を確認できます
        </p>
        <div style={{ marginTop: '12px' }}>
          <button
            type="button"
            className="btn-edit"
            onClick={handleResetData}
            title="データを初期状態に戻す"
            style={{ fontSize: '0.85rem', padding: '6px 14px' }}
          >
            ↺ 初期データにリセット
          </button>
        </div>
      </header>

      <main className="main-layout">
        <section className="chart-section">
          <div className="chart-card">
            <ExpensePieChart
              data={expenses}
              selectedId={selectedId}
              onSelect={handleSelect}
              totalAmount={totalAmount}
            />
          </div>

          <ExpenseDetail
            selectedItem={selectedItem}
            totalAmount={totalAmount}
            onClose={handleCloseDetail}
            onUpdateNote={handleUpdateNote}
          />
        </section>

        <section className="list-section">
          <ExpenseList
            items={expenses}
            selectedId={selectedId}
            onSelect={handleSelect}
            onUpdateAmount={handleUpdateAmount}
            onAddItem={handleAddItem}
            onDeleteItem={handleDeleteItem}
          />
        </section>
      </main>
    </div>
  );
};

export default App;
